You are an expert mathematician. Your task is to provide a thorough and correct proof for a mathematical problem (your Target Problem). This proof will be used to benchmark your abilities as a mathematician.

To obtain your proof, you can assume and use any reference (lemma, theorem, definition, etc) from the context below:

********** BEGIN CONTEXT **********

\section{Preliminary}
\label{sec:pre}

We consider the standard model of online learning with expert advice.

\begin{definition}[Online learning with expert advice]
In an online learning problem, there are $n$ experts and the algorithm is initiated with a memory state $M_0$. At the $t$-th day ($t\in [T]$),
\begin{itemize}
\item The algorithm picks an expert $i_t \in [n]$ bases on its internal state $M_{t-1}$;
\item The nature reveals the loss vector $\ell_{t} \in [0,1]^n$;
\item The algorithm receives loss $\ell_t(i_t)$, observes the loss vector $\ell_t$ and update its memory state from $M_{t-1}$ to $M_{t}$.
\end{itemize}
The loss vector is chosen adversarially:
\begin{itemize}
\item{\textbf{Oblivious adversary.}} An oblivious adversary (randomly) chooses the loss sequence $\ell_1, \ldots, \ell_T$ in advance.
\item{\textbf{Adaptive adversary.}} An adaptive adversary chooses the loss $\ell_t$ at the beginning of day $t$ and it could depend on the past action $i_1, \ldots, i_{t-1}$.
\end{itemize}
An algorithm uses at most $S$ words of memory if $\max_{t\in [T]}|M_t| \leq S$.
\end{definition}

\paragraph{Notation} In an online learning problem, let $T$ be the total number of days, $n$ be the number of experts. Let $[n] = \{1,2, \ldots, n\}$ and $[n_1:n_2] = \{n_1,\ldots, n_2\}$. We sometimes use $\N$ to denote the set of experts. For any integer $t$, let $\mathsf{pw}(t)$ be the largest integer such that $t$ is a multiple of $2^{\mathsf{pw}(t)}$. Let $\Delta_n$ contain all probability distributions over $[n]$.

\begin{algorithm}[!htbp]
\caption{MWU \cite{arora2012multiplicative}}
\label{algo:mwu}
\begin{algorithmic}[1] 
\For{$t=1,2, \ldots, T$}
\State Compute $p_t \in \Delta_n$ over experts such that $p_t(i) \propto \exp(-\eta \sum_{\tau=1}^{t-1}\ell_\tau(i))$ for $i\in [n]$
\State Sample an expert $i_t \sim p_t$ and observe the loss vector $\ell_t \in [0, 1]^n$
\EndFor
\end{algorithmic}
\end{algorithm}

\subsection{The baseline-subroutine building block}
\label{sec:base}

The \textsc{Baseline} (i.e. Algorithm \ref{algo:base}) proceeds epoch by epoch, and each epoch contains $B$ days.

\paragraph{Notation} To formally introduce the concept of covering, we need some notations. 
For any epoch $t\in [T/B]$, let $\mP_{\ell}^{(t)}$ ($\ell \in [0: L]$) be the sub-pool $\mP_{\ell}$ at the beginning of epoch $t$ (after Line \ref{line:base_new} of Algorithm \ref{algo:base}) and 
similarly let  $\mP^{(t)}$ denote the entire pool at the same time.
Our algorithm samples experts with replacement; even if it samples the same expert twice (in different epochs), we will treat it as two separate experts. 
For expert $i \in \mP^{(t)}$, let $E_i \in [T/B]$ denote the time when expert $i$ was sampled and entered the pool. 
For experts $i, j \in \mP^{(t)}$, we write $i \preceq j$ if $E_{i} \leq E_{j}$, i.e., the expert $i$ enters the pool no later than the expert $j$. 
Let $\Gamma_{i, j}$ be the time interval $\{E_{i}, \ldots, E_{j} - 1\}$ ($\Gamma_{i, j} = \emptyset$ if $j$ enters the pool no later than $i$), and slightly abuse of notation, let $\Gamma_{i, t}$ be the time interval $\{E_i, \ldots,  t\}$.
For any interval $\mI \subseteq [T/B]$, the {\em cumulative} loss of expert $i$ over $\mI$ is defined as
\begin{align*}
\mL_{\mathcal{I}}(i) := \sum_{t\in \mathcal{I}}\sum_{b=1}^{B}\ell_{(t-1)B +b}(i).
\end{align*}
In particular, define
\begin{align*}
\mL_{\Gamma_{i, j}}(i) := \left\{
\begin{matrix}
\sum_{t\in \Gamma_{i, j}}\sum_{b=1}^{B}\ell_{(t-1)B +b}(i) & \Gamma_{i, j} \neq \emptyset \\
+\infty & \Gamma_{i, j} = \emptyset
\end{matrix}
\right.
\end{align*}
be the cumulative loss of expert $i$ during interval $\Gamma_{i, j}$. Slightly abusing notation, we set $\mL_{t}(i) = \sum_{b=1}^{B}\ell_{(t-1)B +b}(i)$ to be the total loss of expert $i$ during epoch $t$.

Now we can formally define the {\em cover}.
\begin{definition}[Cover]
\label{def:cover}
Given a set of experts $\mF = \{i_1, \ldots, i_{|\mF|}\}$ and an expert $j\in [n]$. Let $i_1 \preceq i_2 \cdots \preceq i_r \preceq j \preceq i_{r+1} \cdots \preceq i_{|\mF|}$ for some $r \in \{0, 1,2,, \ldots, |\mF|\}$.
At epoch $t$, we say expert $j$ is covered by $\mF$, if 
\begin{align}
\mathcal{L}_{\Gamma_{j,t}}(j) \geq  \min_{i_{r}^{*} \in \mF}\mL_{\Gamma_{j, i_{r+1}}}(i_r^{*}) + \left(\sum_{s = r+1}^{|\mF|}\min_{i_{s}^{*} \in \mF}\mL_{\Gamma_{i_{s}, i_{s+1}}}(i_s^{*})\right)  - 1.
\end{align}
Here we slightly abuse notation and denote $\Gamma_{i_{|\mF|}, i_{|\mF|+1}} = \Gamma_{i_{|\mF|}, t}$.
\end{definition}

\begin{algorithm}[!htbp]
\caption{\textsc{Baseline}}
\label{algo:base}
\begin{algorithmic}[1]
\State Initiate the pool $\mP \leftarrow \emptyset$ and sub-pools $\mP_{\ell} \leftarrow \emptyset$ ($\ell \in [0:L]$) \Comment{$L = \log_2 (T)$}
\For{$t = 1,2, \ldots, T/B$} \Comment{Epoch $t$}
\State $\mP_0 \leftarrow \textsc{Sample}(\N, 1/n)$ \Comment{Sample new experts into the pool}\label{line:base_new}
\State Run MWU over $\mP$ for the next $B$ days \Comment{$\mP = \mP_0 \cup \cdots \cup \mP_{L}$}
\For{$\ell = 0,1, \ldots, \mathsf{pw}(t)$} \Comment{$\mathsf{pw}(t)$ is the largest integer such that $(t/2^{\mathsf{pw}(t)}) \in \mathbb{N}$}
\State $\mP_{\ell+1} \leftarrow \textsc{Merge}(\mP_{\ell+1}, \mP_{\ell})$
\State $\mP_{\ell} \leftarrow \emptyset$
\EndFor 
\EndFor
\end{algorithmic}
\end{algorithm}

\begin{algorithm}[!htbp]
\caption{\textsc{Merge}($\mQ_A, \mQ_B$)}
\label{algo:merge}
\begin{algorithmic}[1]
\State $\mQ_C\leftarrow \mQ_A \cup \mQ_B$
\For{$k=1,2, \ldots, K $} \Comment{$K = 16  \log(nT) $}
\State $s \leftarrow \textsc{EstimateSize}(\mQ_C, \frac{1}{\log^4 (nT)})$   \Comment{Estimate the size of $\mQ_C$}\label{line:merge-estimate}
\If{$s \leq \log^5 (nT)$}
\State Go to Line \ref{line:merge-return} \label{line:threshold}
\Else
\State $\mF_k \leftarrow \textsc{Sample}(\mQ_C, \frac{1}{\log^4 (nT)})$ \Comment{Sample $\frac{1}{\log^4 (nT)}$-fraction of experts}\label{line:merge-sample}
\State $\mQ_C \leftarrow \textsc{Filter}(\mF_{k},\mQ_C) \cup \mF_{k}$
\EndIf
\EndFor
\State Return $\mQ_C$ \label{line:merge-return}
\end{algorithmic}
\end{algorithm}

\begin{algorithm}[!htbp]
\caption{\textsc{EstimateSize}($\mQ, p$)}
\label{algo:estimate}
\begin{algorithmic}[1]
\State $p_{i} \leftarrow \text{Bernoulli}(p)$ for every $i \in \mQ$
\State Return $\sum_{i \in \mQ}p_i$
\end{algorithmic}
\end{algorithm}

\begin{algorithm}[!htbp]
\caption{\textsc{Sample}($\mQ, p$)}
\label{algo:sample}
\begin{algorithmic}[1]
\State $p_{i} \leftarrow \text{Bernoulli}(p)$ for every $i \in \mQ$
\State Return $\{i\in \mQ: p_{i} = 1\}$
\end{algorithmic}
\end{algorithm}

\begin{algorithm}[!htbp]
\caption{\textsc{Filter}($\mF, \mQ$)}
\label{algo:filter}
\begin{algorithmic}[1]
\For{each expert $i \in \mQ$}
\If{$\mF$ covers $i$} \Comment{Definition \ref{def:cover}}
\State $\mQ \leftarrow \mQ \setminus \{i\}$
\EndIf
\EndFor
\State Return $\mQ$
\end{algorithmic}
\end{algorithm}

\begin{lemma}
\label{lem:merge_size}
With probability at least $1-1/(nT)^{\omega(1)}$, the output $\mQ_{C}$ of {\sc Merge} procedure satisfies \begin{align*}
|\mQ_{C}| \leq \max\left\{2\log^9 (nT), \frac{1}{4}(|\mQ_A| + |\mQ_{B}|)\right\}.
\end{align*}
\end{lemma}

\subsection{Boosting}
\label{sec:bootstrap-optimal}

\paragraph{Full algorithm}
The full algorithm is presented as Algorithm \ref{algo:full}. WLOG, we assume $T/n$ is a tower of $2$.
Let $R = \log_2(T/n) $ be the total number of threads.
Let $B_{r} = \frac{T}{n 2^{r-1}}$ ($r \in [R]$), $T_1 = T$ and $T_{r} = B_{r-1}$ for $r\in [2:R]$.

\begin{algorithm}[!htbp]
\caption{Full algorithm}
\label{algo:full}
\begin{algorithmic}[1]
\State Initialize $\textsc{Baseline}_{+}(r)$ ($\forall\, r\in [R]$) \Comment{$\textsc{Baseline}_{+}(r)$ maintains the pool $\mP_{r,\cdot}$}
\State $\mP \leftarrow \mP_{1,\cdot}\cup \cdots \cup \mP_{R,\cdot}$ \Comment{$\mP$ aggregates pools from all threads}
\For{$t = 1,2, \ldots, T$}
\State Run $\textsc{Baseline}_{+}(r)$ ($r\in [R]$) 
\State Run {\sc MonocarpicExpert} over $\mP$ 
\EndFor
\end{algorithmic}
\end{algorithm}

\begin{algorithm}[!htbp]
\caption{$\textsc{Baseline}_{+}(r)$ \Comment{$r \in [R]$}
}
\label{algo:base+}
\begin{algorithmic}[1]
\For{$s = 1,2,\ldots, T/T_{r}$} \Comment{$s$-th restart}
\State Initiate the pool $\mP_{r,\cdot} \leftarrow \emptyset$ and sub-pools $\mP_{r, \ell} \leftarrow \emptyset$ ($i \in [0:L]$)
\For{$t = 1,2, \ldots, T_r/B_r$} \Comment{Epoch $t$} 
\State \texttt{// At the beginning of epoch $t$  } \If{$r$ is the lowest thread with a new epoch}\label{line:cont-merge1} \For{$r' = R, \ldots, r+1$} 
\State $\mP_{r,0} \leftarrow \textsc{Merge}(\mP_{r, 0} \cup \mP_{r', \cdot}$) \Comment{Inherit from higher thread pools}
\EndFor 
\EndIf\label{line:cont-merge2}
\State $\mP_{r,0} \leftarrow \mP_{r,0} \cup \textsc{Sample}(\N, 1/n)$ \Comment{Sample new experts into pool} \label{line:base_new+}\\
\State \texttt{// At the end of epoch $t$  }\For{$\ell = 0,1, \ldots, \mathsf{pw}(t)$}
\State $\mP_{r,\ell+1} \leftarrow \textsc{Merge}(\mP_{r,\ell+1}, \mP_{r,\ell})$
\State $\mP_{r,\ell} \leftarrow \emptyset$
\EndFor 
\EndFor
\EndFor
\end{algorithmic}
\end{algorithm}

\subsubsection{{\sc MonocarpicExpert}}
\label{sec:sleep}

The set of experts is divided into $L$ subsets $\mU_{1} \cup \cdots \cup \mU_{L}$ ($L = \log_2 (T)$), and $\mU_{\ell}$ contains experts that live for at most $2^{\ell}$ days. 

\begin{algorithm}[!htbp]
\caption{\textsc{MonocarpicExpert} 
}
\label{algo:sleep}
\begin{algorithmic}[1]
\State Initialize $\mU_\ell \leftarrow \emptyset$, $\textsc{Exp}_{\ell}$ ($\ell \in [L]$) \Comment{$L = \log_2(T) $}
\State $\textsc{Exp}\leftarrow \textsc{IntervalRegret}(\textsc{Exp}_1, \ldots, \textsc{Exp}_{L}, T)$
\For{$t=1,2, \ldots, T$}
\State Add newly activated experts to $\mU_1$  
\State Follow the decision of $\textsc{Exp}$
\For{$\ell = 1,2, \ldots, \mathsf{pw}(t)$} \Comment{Update membership}
\State $\mU_{\ell+1} \leftarrow \mU_{\ell+1} \cup \mU_{\ell}, \mU_{\ell} \leftarrow \emptyset$
\State Remove inactive experts in $\mU_{\ell+1}$
\EndFor
\EndFor\\ 

\Procedure{$\textsc{Exp}_{\ell}$}{} \Comment{$\ell \in [L]$}
\For{$s=1,2,\ldots, T/2^{\ell-1}$}\Comment{$s$-th restart}
\State $\textsc{IntervalRegret}(\mU_{\ell}, 2^{\ell-1})$
\EndFor
\EndProcedure
\end{algorithmic}
\end{algorithm}

\begin{lemma}
\label{lem:interval}
Let $T \geq 1$. For any expert $i \in \mU$ and time interval $\mI \subseteq [T]$, Algorithm {\sc IntervalRegret} guarantees that with probability at least $1 - 1/(nT)^{\omega(1)}$,
\begin{align*}
\sum_{t \in \mathcal{I}}\ell_t(i_t) - \sum_{t \in \mathcal{I}}\ell_t(i) \leq O\left(\sqrt{|\mathcal{I}|\log (nT)}\right)
\end{align*}
holds against an adaptive adversary.
Moreover, {\sc IntervalRegret} uses up to $O(|\mU|\log(nT))$ words of memory.
\end{lemma}

\begin{algorithm}[!htbp]
\caption{\textsc{IntervalRegret}($\mU, T$)}
\label{algo:interval}
\begin{algorithmic}[1]
\State Initialize $w_{a, b} \leftarrow 1$ over $\textsc{SingleInterval}_{a,b}$ ($a \in [L], b \in [T/2^a]$)
\For{$t=1,2, \ldots, T$}
\State Sample action $i_{t, a,b}$ from $\{w_{a, b}\}_{h(t, a, b) =1}$  \Comment{$h(t, a, b) = 1$ if $t \in [2^a(b-1)+1: 2^a b]$}
\State Compute the expected loss
\begin{align}
\bar{\ell}_t \leftarrow \sum_{a, b: h(t, a, b) = 1}\frac{w_{a, b}}{\sum_{a, b: h(t, a, b) = 1} w_{a, b} } \cdot \ell_{t}(i_{t, a, b})
\label{eq:loss-construct}
\end{align}
\State Assign loss 
\[
\hat{\ell}_{t}( a, b ) = \left\{
\begin{matrix}
\ell_{t}(i_{t, a, b}) &  h(t, a, b) =1\\
\bar{\ell}_t & h(t, a, b) =0
\end{matrix}
\right.
\]
\State Update the weight distribution using {\sc Squint}
\begin{align}
w_{a, b}  \leftarrow \E_{\eta}\left[\eta \cdot \exp\left(\eta \sum_{\tau=1}^{t-1}v_{\tau}(a, b) - \eta^2 \sum_{\tau=1}^{t-1}v_{\tau}^2(a, b)\right)\right] \label{eq:squint}
\end{align}
where $v_{\tau}(a, b) = \bar{\ell}_{\tau} - \hat{\ell}_{\tau}(a, b)$
\EndFor\\
\Procedure{$\textsc{SingleInterval}_{a, b}$}{}
\For{$t = 2^{a}(b-1) +1, \ldots, 2^{a}b$}
\State Run MWU over $\mU$.
\EndFor
\EndProcedure
\end{algorithmic}
\end{algorithm}

\subsubsection*{Regret analysis}

\paragraph{Notation} 
Let $i^{*} \in [n]$ be the best expert and let
\[
K_1 = [0:n-1], \quad K_2 = [0:n-1]\times \{0,1\}  \quad \ldots  \quad K_R=  [0:n-1] \times \underbrace{\{0,1\}\times \cdots \times \{0,1\}}_{R-1}
\]
and $K$ be the union of $K_1, \ldots, K_R$, i.e.,
\[
K = K_1 \cup \cdots \cup K_{R}.
\]
Given any timestep $a = (a_{1}, \ldots, a_{r(a)}) \in K$ (where $r(a)$ is defined such that $a \in K_{r(a)}$), the timestep $a$ uniquely identifies an epoch of $\textsc{Baseline}_{+}(r(a))$, i.e., it refers to the $a_{r(a)}$-th epoch of the $(\sum_{r =1}^{r(a)-1}a_r 2^{r(a)-r-1})$-th restart.

\begin{definition}[Operator $\oplus$]
For any timestep $a\in K$, we write 
\[
a'  = (a_1', a_2', \ldots a_{r(a')}') = a\oplus 1 \in K 
\]
as the unique timestep that satisfies
\[
\sum_{i=1}^{r(a')} a_i'B_i = \sum_{i=1}^{r(a)} a_i B_i + B_{r(a)} \quad \text{and} \quad a'_{r(a')} \neq 0. 
\]
That is to say, $a' = a \oplus 1$ is the next number under $2$-base with $0$ truncated at the end  (except the first coordinate, which belongs to $[0:n-1]$).
\end{definition}

Let $K(a)$ contain all timesteps that succeed $a$ under the $\oplus$ operation, i.e., 
\[
K(a) := \{a\} \cup \{a \oplus 1\} \cup \{(a \oplus 1) \oplus 1\} \cup \cdots  \subseteq K 
\]

\paragraph{Random bits} 
For any timestep $a \in K$, let the random bits $\xi_{a} = (\xi_{a, 1}, \ldots, \xi_{a, n})$, where $\xi_{a, i} = (\xi_{a,i, 1}, \xi_{a, i,2})$ is used for expert $i$ ($i \in [n]$).
The first coordinate $\xi_{a, i, 1} \in \{0, 1\}$ is a Bernoulli variable with mean $1/n$. It is used for sampling new expert into the pool at the beginning of epoch $a$ (i.e. Line \ref{line:base_new+} of Algorithm \ref{algo:base+}).
The second part of random bits $\xi_{a, i, 2} \in \{0, 1\}^{R \times 2L \times 2K}$ are used for estimating size and filtering in the {\sc Merge} procedure of each sub-pool, they are of mean $\frac{1}{\log^4 (nT)}$.

\begin{definition}[Active/Passive expert]
At any timestep $a \in K$, an expert $i\in [n]$ is said to be {\em passive}, if $\xi_{a, i, 2} = \vec{0}$. It is said to be an {\em active} expert otherwise.
\end{definition}

\paragraph{Epoch Assignment}  

\begin{definition}[Eviction time, full algorithm]
For any timestep $a \in K$, consider the expert $i^{*}$ with entering time $a$, the eviction time $t(a) \in K(a)\cup \{+\infty\}$ is defined as the first timestep of $K(a)$, such that $i^{*}$ is covered by the set of alive active experts at the end of $t(a)$.
If $i^{*}$ would not be covered, then set $t(a) = +\infty$.
\end{definition}

\begin{algorithm}[!htbp]
\caption{Epoch assignment (Note: only used in analysis)}
\label{algo:sequence}
\begin{algorithmic}[1]
\State Initialize $\mH_{r} \leftarrow \emptyset$ ($r\in [R]$), $\tau \leftarrow 1$, $a_{1} \leftarrow 0$
\While{$\cup_{\tau'\leq \tau}\mI_{\tau'}  \neq [T]$}
\If{$t(a_{\tau}) = +\infty$}\Comment{$i^{*}$ survives till the end} 
\State $\mH_{r(a_{\tau})} \leftarrow \mH_{r(a_{\tau})} \cup a_{\tau}$ \Comment{$a_\tau$ is a bad epoch at thread $r(a_\tau)$}\label{line:augment}
\If{$r(a_{\tau}) = R$} \Comment{Stop at the top thread}
\State $\mI_{\tau} \leftarrow a_\tau$, $a_{\tau + 1} \leftarrow a_{\tau} \oplus 1$, $\tau \leftarrow \tau + 1$, 
\Else 
\State $a_{\tau} \leftarrow (a_{\tau}, 0)$ \Comment{Move to next thread}
\EndIf
\Else
\State $a_{\tau + 1} \leftarrow t(a_{\tau}) \oplus 1$, $I_{\tau} \leftarrow [a_{\tau}: t(a_{\tau})]$, $\tau \leftarrow \tau + 1$
\EndIf
\EndWhile
\end{algorithmic}
\end{algorithm}

The key ingredient in our analysis is the epoch assignment mechanism, whose pseudocode is presented as Algorithm \ref{algo:sequence} (note again that this algorithm is only for analysis). Algorithm \ref{algo:sequence} splits the entire sequence and determines the bad epochs $\mH_{r}$ of each thread $r$ ($r\in [R]$) through a bottom-up walk.
It starts from the bottom thread $r=1$. 
At each step $\tau$, if the expert $i^{*}$ could survive till the end with entering time $a_{\tau}$, then it is a bad epoch at thread $r(a_{\tau})$ and the algorithm augments the collection of bad epochs $\mH_{r(a_{\tau})}$ of thread $r(a_{\tau})$ (Line \ref{line:augment}). 
Instead of moving to the next epoch of the same thread, Algorithm~\ref{algo:sequence} walks to the next thread, unless it is already at the top thread $R$. 
If the expert $i^{*}$ would be covered until timestep $t(a_{\tau}) \in K(a)$, 
then Algorithm~\ref{algo:sequence} sets the $\tau$-th interval as $\mI_{\tau} = [a_{\tau}:t(a_{\tau})]$ and moves to the next epoch $a_{\tau+1} = t(a_{\tau})\oplus 1$.  
Here $a_{\tau}$ and $t(a_{\tau})$ do not need to be at the same thread, and we write $\mI_{\tau} = [a_{\tau}:t(a_{\tau})]$ to denote the time interval between the beginning of $a_\tau$ and the end of $t(a_{\tau})$.

Let $\tau_{\max}$ be the total number of intervals in the partition generated by Algorithm~\ref{algo:sequence}.


