We start by proving the following 2 auxiliary statements:

\begin{lemma}
\label{lem:pool_size_full}
With probability at least $1 - 1/(nT)^{\omega(1)}$, for any $r \in [R]$, the pool $\mP_{r, \cdot}$ never exceeds $O(\log^{10}(nT))$.
\end{lemma}
\begin{proof}
We prove with probability at least $1- 1/(nT)^{\omega(1)}$, at any time, the size of $\mP_{r, \ell}$ is at most $2\log^9 (nT)$ ($r \in [R]$, $\ell \in [L]$) and $\mP_{r, 0}$ is at most $3\log^9 (nT)$.  
The case of $r = R$ holds trivially and suppose the induction holds for thread $r+1$. 

For the $r$-th thread, $\mP_{r, 0}$ is initiated as $\textsc{Sample}(\mN, 1/n)$, or the union of $\textsc{Sample}(\mN, 1/n)$ and the result of merging $\mP_{r+1, \cdot}, \ldots, \mP_{R, \cdot}$ (Line \ref{line:cont-merge1} -- \ref{line:cont-merge2} of Algorithm \ref{algo:base+}).
We have by induction $|\mP_{r', \cdot}| = |\mP_{r', 2}| \leq 2\log^9 (nT)$ for any $r' > r$ (there are only two epochs of  $\textsc{Baseline}_{+}(r')$ per restart). Hence by Lemma \ref{lem:merge_size}, the pool obtained from merging  $\mP_{r+1, \cdot}, \ldots, \mP_{R, \cdot}$ has size at most $2\log^9(nT)$, and by Chernoff bound, the sample set $\textsc{Sample}(\mN, 1/n)$ is at most $\log^9(nT)$ with high probability. 

While for $\ell \geq 1$, by Lemma \ref{lem:merge_size}, the \textsc{Merge} procedure guarantees that the sub-pool $\mP_{r, \ell}$ satisfies
\begin{align*}
|\mP_{r, \ell}| \leq &~ \max\left\{2\log^9(nT), \frac{1}{4}(|\mP_{r, \ell}| + |\mP_{r, \ell-1}|)\right\}\\
\leq &~ \max\left\{2\log^9(nT), \frac{1}{4}(2\log^9(nT) + 3\log^9(nT))\right\} = 2\log^9(nT).
\end{align*}
\end{proof}

\begin{theorem}
\label{thm:sleeping}
Let $T \geq 1$. For any expert $i$ that is alive over interval $\mathcal{I} \subseteq [T]$, the {\sc MonocarpicExpert} procedure (Algorithm \ref{algo:sleep}) guarantees that with probability at least $1-1/(nT)^{\omega(1)}$, 
\begin{align*}
\sum_{t \in \mathcal{I}'}\ell_t(i_t) - \sum_{t \in \mathcal{I}'}\ell_t(i) \leq O\left(\sqrt{|\mathcal{I'}|\log (nT)}\right)
\end{align*}
holds for every interval $\mI'\subseteq  \mI$, against an adaptive adversary.
Furthermore, suppose the maximum number of alive experts at most $M$, then the {\sc MonocarpicExpert} procedure uses up to $O(M\log^2(nT))$ words of memory.
\end{theorem}
\begin{proof}[Proof of Theorem \ref{thm:sleeping}]
We first provide the regret analysis. 
For any expert $i$ that is alive over interval $\mI$. Let $\mI' = [t_1: t_2] \subseteq \mI$ be any sub-interval. One can split the interval $\mI'$ into $X \leq \log(|\mI'|)$ consecutive intervals $\mI' = \mI'_1 \cup \mI'_2 \cup \ldots \cup \mI'_X$, such that expert $i$ resides in $\mU_{\ell_x}$ during the interval of $\mI'_x$ ($\ell_1 < \ell_2 < \cdots < \ell_{X}$).
Moreover, the size of $\mI'_x$ is exponentially increasing, except for $\mI'_1$ and $\mI'_X$
($i$ may not stay for an entire update at $\mU_{\ell_1}$ and $\mU_{\ell_X}$).
Let $i_{t,\ell}$ be the action of $\textsc{Exp}_{\ell}$ at day $t$, Then due to the {\sc IntervalRegret} guarantee, with probability at least $1-1/(nT)^{\omega(1)}$, one has
\begin{align*}
\sum_{t \in \mI'}\ell_{t}(i_t) - \sum_{t \in \mI'}\ell_t(i) =  &~ \sum_{x=1}^{X}\sum_{t \in \mI'_{x}}\ell_{t}(i_t) - \ell_t(i) \\
= &~ \sum_{x=1}^{X}\sum_{t \in \mI'_{x}}\ell_{t}(i_{t}) - \ell_t(i_{t, \ell_x}) +  \sum_{x=1}^{X}\sum_{t \in \mI'_{x}}\ell_{t}(i_{t, \ell_x}) - \ell_t(i)\\
\leq &~ \sum_{x=1}^{X} O(\sqrt{|\mI_{x}'|\log (nT)}) \leq O(\sqrt{|\mI'|\log (nT)}).
\end{align*}
Here the third step follows from the interval guarantee (see Lemma \ref{lem:interval}) of $\textsc{Exp}_{\ell_x}$, the interval regret guarantee of $\textsc{Exp}_{\ell_x}$ on $\mU_{\ell_{x}}$,  and the fact that $\textsc{Exp}_{\ell_x}$ restarts at most twice when $i$ resides in $\mU_{\ell_x}$.
The last step follows from the increasing size of $\mI_{x}'$. 

Finally, for the memory usage, there are $L = \log_2(T)$ procedures $\textsc{Exp}_{\ell}$ ($\ell \in [L]$), and $\textsc{Exp}_{\ell}$ runs on $\mU_{\ell}$.
It suffices to bound the size of $\mU_{\ell}$. 
Note that $\mU_{\ell}$ is updated every $2^{\ell-1}$ days, and at the time of update, all experts in $\mU_{\ell}$ are alive and the set remains the same during the next $2^{\ell-1}$ days. Hence $|\mU_{\ell}| \leq M$ and the memory usage of $\textsc{Exp}_{\ell}$ is at most $O(M\log (nT))$.  
The total memory is at most $O(M\log^2(nT))$.
\end{proof}

With the above in mind, we are now ready to prove the main statement:

\begin{proof}
We condition on the event of Lemma \ref{lem:pool_size_full}.
Given any interval $I_{\tau}$ starting with $a_\tau$, ending with $t(a_{\tau})$ and $a_{\tau} \notin \mH_{R}$, the expert $i^{*}$ with entering time $a_\tau$ is covered by $\mP$ the end of $t(a_{\tau})$. Let $i_1^{*}, \ldots, i_{s}^{*}$ be the set of experts that cover $i^{*}$.
By Definition \ref{def:cover}, we can partition the interval $\mI_{\tau} = \mI_{\tau, 1} \cup \cdots \cup \mI_{\tau, s}$ and obtain
\begin{align}
\label{eq:mg1}
\sum_{t \in \mI_{\tau}}\ell_{t}(i^{*}) \geq \sum_{j=1}^{s}\sum_{t\in \mI_{\tau, j}}\ell_t(i_{j}^{*}) - 1
\end{align}
By the regret guarantee of {\sc MonocarpicExpert}, with probability at least $1 - 1/(nT)^{\omega(1)}$, one has
\begin{align}
\sum_{t \in \mI_{\tau}}\ell_{t}(i_t) - \sum_{t \in \mI_{\tau}}\ell_{t}(i^{*}) = &~ \sum_{t \in \mI_{\tau}} \ell_{t}(i_t) - \sum_{j=1}^{s}\sum_{t\in \mI_{\tau, j}}\ell_t(i_{j}^{*}) +  \sum_{j=1}^{s}\sum_{t\in \mI_{\tau, j}}\ell_t(i_{j}^{*}) - \sum_{t \in \mI_{\tau}}\ell_{t}(i^{*})\notag\\
\leq &~ \sum_{j=1}^{s}O\left(\sqrt{|\mI_{\tau, j}|\log(nT)}\right) + \sum_{j=1}^{s}\sum_{t\in \mI_{\tau, j}}\ell_t(i_{j}^{*})  - \sum_{t \in \mI_{\tau}}\ell_{t}(i^{*}) \notag  \\
\leq &~ \sum_{j=1}^{s}O\left(\sqrt{|\mI_{\tau, j}|\log(nT)}\right) + 1\notag \\
\leq &~ \sqrt{|\mI_{\tau}|} \cdot \log^{6}(nT).\notag\end{align}
The second step follows from Theorem \ref{thm:sleeping}, the third step follows from Eq.~\eqref{eq:mg1} and the last step follows from $s \leq \log^{11}(nT)$ (Lemma \ref{lem:pool_size_full}), $\mI_{\tau} = \mI_{\tau, 1} \cup \cdots \cup \mI_{\tau, s}$ and Cauchy-Schwarz. We conclude the proof here.

\end{proof}
